const express = require('express');
const { db } = require('../database');

const app = express();
const invoiceSubApp = express({ mergeParams: true });

// Tenant authorization middleware on mounted path
app.use('/tenants/:tenantId/invoices', (req, res, next) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Enforce that path tenant parameter matches caller's authenticated tenant
  if (req.user.tenantId !== req.params.tenantId && req.user.role !== 'SUPER_ADMIN') {
    return res.status(403).json({ error: 'Access forbidden: tenant mismatch' });
  }

  next();
}, invoiceSubApp);

invoiceSubApp.get('/:invoiceId', async (req, res) => {
  // Query must strictly enforce tenant ownership on the object itself
  const invoice = await db.invoices.findOne({
    _id: req.params.invoiceId,
    tenantId: req.params.tenantId
  });

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found or access denied' });
  }

  res.json({ invoice });
});

app.listen(8080);
